ailable' | 'compact' | 'viewport'\n  }\n>()\nconst emits = defineEmits<DropdownMenuContentEmits>()\nconst forwarded = useForwardPropsEmits(restProps, emits)\nconst rootContext = injectDropdownMenuRootContext()\nconst contentStyle = useModalLiftedZIndex(rootContext.open)\n</script>\n\n<template>\n  <DropdownMenuContent\n    v-bind=\"forwarded\"\n    :style=\"contentStyle\"\n    :class=\"\n      cn(\n        menuContentClass,\n        width === 'trigger' &&\n          'w-(--reka-dropdown-menu-trigger-width) min-w-0 overflow-hidden',\n        width === 'compact' && 'w-max min-w-46.5',\n        maxHeight === 'available' &&\n          'max-h-(--reka-dropdown-menu-content-available-height)',\n        maxHeight === 'compact' && 'max-h-64',\n        maxHeight === 'viewport' &&\n          'max-h-[min(40vh,var(--reka-dropdown-menu-content-available-height))]',\n        className\n      )\n    \"\n  >\n    <slot />\n  </DropdownMenuContent>\n</template>\n","<script setup lang=\"ts\">\nimport type {\n  DropdownMenuContentEmits,\n  DropdownMenuContentProps\n} from 'reka-ui'\nimport {\n  DropdownMenuContent,\n  injectDropdownMenuRootContext,\n  useForwardPropsEmits\n} from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { useModalLiftedZIndex } from '@/composables/useModalLiftedZIndex'\n\nimport { menuContentClass } from './menuStyles'\n\nconst {\n  class: className,\n  width = 'default',\n  maxHeight = 'available',\n  ...restProps\n} = defineProps<\n  DropdownMenuContentProps & {\n    class?: HTMLAttributes['class']\n    width?: 'default' | 'trigger' | 'compact'\n    maxHeight?: 'available' | 'compact' | 'viewport'\n  }\n>()\nconst emits = defineEmits<DropdownMenuContentEmits>()\nconst forwarded = useForwardPropsEmits(restProps, emits)\nconst rootContext = injectDropdownMenuRootContext()\nconst contentStyle = useModalLiftedZIndex(rootContext.open)\n</script>\n\n<template>\n  <DropdownMenuContent\n    v-bind=\"forwarded\"\n    :style=\"contentStyle\"\n    :class=\"\n      cn(\n        menuContentClass,\n        width === 'trigger' &&\n          'w-(--reka-dropdown-menu-trigger-width) min-w-0 overflow-hidden',\n        width === 'compact' && 'w-max min-w-46.5',\n        maxHeight === 'available' &&\n          'max-h-(--reka-dropdown-menu-content-available-height)',\n        maxHeight === 'compact' && 'max-h-64',\n        maxHeight === 'viewport' &&\n          'max-h-[min(40vh,var(--reka-dropdown-menu-content-available-height))]',\n        className\n      )\n    \"\n  >\n    <slot />\n  </DropdownMenuContent>\n</template>\n","import { useEventListener } from '@vueuse/core'\n\nexport const whileMouseDown = (\n  elementOrEvent: HTMLElement | Event,\n  callback: (iteration: number) => void,\n  interval: number = 30\n) => {\n  const element =\n    elementOrEvent instanceof HTMLElement\n      ? elementOrEvent\n      : (elementOrEvent.target as HTMLElement)\n\n  let iteration = 0\n\n  const intervalId = setInterval(() => {\n    callback(iteration++)\n  }, interval)\n\n  const dispose = () => {\n    clearInterval(intervalId)\n    disposeGlobal()\n    disposeLocal()\n  }\n\n  // Listen for mouseup globally to catch cases where user drags out of element\n  const disposeGlobal = useEventListener(document, 'mouseup', dispose)\n  const disposeLocal = useEventListener(element, 'mouseup', dispose)\n\n  return {\n    dispose: dispose\n  }\n}\n","<script setup lang=\"ts\">\nimport { createReusableTemplate } from '@vueuse/core'\nimport { DropdownMenuCheckboxItem, DropdownMenuItem } from 'reka-ui'\nimport { onBeforeUnmount, toValue } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TextTooltip from '@/components/ui/tooltip/TextTooltip.vue'\nimport { whileMouseDown } from '@/utils/mouseDownUtil'\n\nimport { menuItemClass } from './menuStyles'\nimport type { MenuItemAction } from './types'\n\nconst { allowCommandless = false, item } = defineProps<{\n  allowCommandless?: boolean\n  item: MenuItemAction\n}>()\n\nconst emit = defineEmits<{\n  select: []\n}>()\n\nconst [DefineItem, ReuseItem] = createReusableTemplate()\n\nlet pointerRepeating = false\nlet stopRepeating: (() => void) | undefined\n\nonBeforeUnmount(() => stopRepeating?.())\n\nfunction mouseDown(event: MouseEvent) {\n  if (\n    event.button !== 0 ||\n    toValue(item.disabled) ||\n    !item.command ||\n    item.pressAndHoldInterval === undefined\n  )\n    return\n  stopRepeating?.()\n  pointerRepeating = false\n  const { dispose } = whileMouseDown(\n    event,\n    () => {\n      pointerRepeating = true\n      void item.command?.({ originalEvent: event, item })\n    },\n    item.pressAndHoldInterval\n  )\n  stopRepeating = dispose\n}\n\nfunction select(event: Event) {\n  if (!item.command) {\n    event.preventDefault()\n    return\n  }\n  if (item.checked !== undefined) {\n    event.preventDefault()\n    void item.command({ originalEvent: event, item })\n    return\n  }\n  if (pointerRepeating) {\n    pointerRepeating = false\n    event.preventDefault()\n    return\n  }\n  void item.command({ originalEvent: event, item })\n  if (event.defaultPrevented) return\n  if (item.pressAndHoldInterval !== undefined) {\n    event.preventDefault()\n    return\n  }\n  emit('select')\n}\n</script>\n\n<template>\n  <DefineItem>\n    <component\n      :is=\"\n        item.checked === undefined ? DropdownMenuItem : DropdownMenuCheckboxItem\n      \"\n      :aria-label=\"toValue(item.label)\"\n      :aria-description=\"toValue(item.description)\"\n      :disabled=\"toValue(item.disabled) || (!item.command && !allowCommandless)\"\n      :class=\"\n        cn(\n          menuItemClass,\n          item.variant === 'destructive' && 'text-destructive-background',\n          toValue(item.class)\n        )\n      \"\n      :model-value=\"toValue(item.checked)\"\n      @mousedown=\"mouseDown\"\n      @keydown.capture=\"pointerRepeating = false\"\n      @select=\"select\"\n    >\n      <slot />\n    </component>\n  </DefineItem>\n  <TextTooltip v-if=\"item.tooltip\" :text=\"item.tooltip\" side=\"right\">\n    <ReuseItem />\n  </TextTooltip>\n  <ReuseItem v-else />\n</template>\n","<script setup lang=\"ts\">\nimport { createReusableTemplate } from '@vueuse/core'\nimport { DropdownMenuCheckboxItem, DropdownMenuItem } from 'reka-ui'\nimport { onBeforeUnmount, toValue } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TextTooltip from '@/components/ui/tooltip/TextTooltip.vue'\nimport { whileMouseDown } from '@/utils/mouseDownUtil'\n\nimport { menuItemClass } from './menuStyles'\nimport type { MenuItemAction } from './types'\n\nconst { allowCommandless = false, item } = defineProps<{\n  allowCommandless?: boolean\n  item: MenuItemAction\n}>()\n\nconst emit = defineEmits<{\n  select: []\n}>()\n\nconst [DefineItem, ReuseItem] = createReusableTemplate()\n\nlet pointerRepeating = false\nlet stopRepeating: (() => void) | undefined\n\nonBeforeUnmount(() => stopRepeating?.())\n\nfunction mouseDown(event: MouseEvent) {\n  if (\n    event.button !== 0 ||\n    toValue(item.disabled) ||\n    !item.command ||\n    item.pressAndHoldInterval === undefined\n  )\n    return\n  stopRepeating?.()\n  pointerRepeating = false\n  const { dispose } = whileMouseDown(\n    event,\n    () => {\n      pointerRepeating = true\n      void item.command?.({ originalEvent: event, item })\n    },\n    item.pressAndHoldInterval\n  )\n  stopRepeating = dispose\n}\n\nfunction select(event: Event) {\n  if (!item.command) {\n    event.preventDefault()\n    return\n  }\n  if (item.checked !== undefined) {\n    event.preventDefault()\n    void item.command({ originalEvent: event, item })\n    return\n  }\n  if (pointerRepeating) {\n    pointerRepeating = false\n    event.preventDefault()\n    return\n  }\n  void item.command({ originalEvent: event, item })\n  if (event.defaultPrevented) return\n  if (item.pressAndHoldInterval !== undefined) {\n    event.preventDefault()\n    return\n  }\n  emit('select')\n}\n</script>\n\n<template>\n  <DefineItem>\n    <component\n      :is=\"\n        item.checked === undefined ? DropdownMenuItem : DropdownMenuCheckboxItem\n      \"\n      :aria-label=\"toValue(item.label)\"\n      :aria-description=\"toValue(item.description)\"\n      :disabled=\"toValue(item.disabled) || (!item.command && !allowCommandless)\"\n      :class=\"\n        cn(\n          menuItemClass,\n          item.variant === 'destructive' && 'text-destructive-background',\n          toValue(item.class)\n        )\n      \"\n      :model-value=\"toValue(item.checked)\"\n      @mousedown=\"mouseDown\"\n      @keydown.capture=\"pointerRepeating = false\"\n      @select=\"select\"\n    >\n      <slot />\n    </component>\n  </DefineItem>\n  <TextTooltip v-if=\"item.tooltip\" :text=\"item.tooltip\" side=\"right\">\n    <ReuseItem />\n  </TextTooltip>\n  <ReuseItem v-else />\n</template>\n","<template>\n  <span class=\"relative inline-flex size-[1em] items-center justify-center\">\n    <i :class=\"mainIcon\" class=\"text-[1em]\" />\n    <i\n      :class=\"\n        cn(\n          subIcon,\n          'pointer-events-none absolute leading-none',\n          positionX === 'left' ? 'left-0' : 'right-0',\n          positionY === 'top' ? 'top-0' : 'bottom-0'\n        )\n      \"\n      :style=\"subIconStyle\"\n    />\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype Position = 'top' | 'bottom' | 'left' | 'right'\n\nexport interface OverlayIconProps {\n  mainIcon: string\n  subIcon: string\n  positionX?: Position\n  positionY?: Position\n  offsetX?: number\n  offsetY?: number\n  subIconScale?: number\n}\nconst {\n  mainIcon,\n  subIcon,\n  positionX = 'right',\n  positionY = 'bottom',\n  offsetX = 0,\n  offsetY = 0,\n  subIconScale = 0.6\n} = defineProps<OverlayIconProps>()\n\nconst textShadow = [\n  `-1px -1px 0 rgba(0, 0, 0, 0.7)`,\n  `1px -1px 0 rgba(0, 0, 0, 0.7)`,\n  `-1px 1px 0 rgba(0, 0, 0, 0.7)`,\n  `1px 1px 0 rgba(0, 0, 0, 0.7)`,\n  `-1px 0 0 rgba(0, 0, 0, 0.7)`,\n  `1px 0 0 rgba(0, 0, 0, 0.7)`,\n  `0 -1px 0 rgba(0, 0, 0, 0.7)`,\n  `0 1px 0 rgba(0, 0, 0, 0.7)`\n].join(', ')\n\nconst subIconStyle = computed(() => ({\n  fontSize: `${subIconScale}em`,\n  textShadow,\n  ...(offsetX !== 0 && {\n    [positionX === 'left' ? 'left' : 'right']: `${offsetX}px`\n  }),\n  ...(offsetY !== 0 && {\n    [positionY === 'top' ? 'top' : 'bottom']: `${offsetY}px`\n  })\n}))\n</script>\n","<template>\n  <span class=\"relative inline-flex size-[1em] items-center justify-center\">\n    <i :class=\"mainIcon\" class=\"text-[1em]\" />\n    <i\n      :class=\"\n        cn(\n          subIcon,\n          'pointer-events-none absolute leading-none',\n          positionX === 'left' ? 'left-0' : 'right-0',\n          positionY === 'top' ? 'top-0' : 'bottom-0'\n        )\n      \"\n      :style=\"subIconStyle\"\n    />\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype Position = 'top' | 'bottom' | 'left' | 'right'\n\nexport interface OverlayIconProps {\n  mainIcon: string\n  subIcon: string\n  positionX?: Position\n  positionY?: Position\n  offsetX?: number\n  offsetY?: number\n  subIconScale?: number\n}\nconst {\n  mainIcon,\n  subIcon,\n  positionX = 'right',\n  positionY = 'bottom',\n  offsetX = 0,\n  offsetY = 0,\n  subIconScale = 0.6\n} = defineProps<OverlayIconProps>()\n\nconst textShadow = [\n  `-1px -1px 0 rgba(0, 0, 0, 0.7)`,\n  `1px -1px 0 rgba(0, 0, 0, 0.7)`,\n  `-1px 1px 0 rgba(0, 0, 0, 0.7)`,\n  `1px 1px 0 rgba(0, 0, 0, 0.7)`,\n  `-1px 0 0 rgba(0, 0, 0, 0.7)`,\n  `1px 0 0 rgba(0, 0, 0, 0.7)`,\n  `0 -1px 0 rgba(0, 0, 0, 0.7)`,\n  `0 1px 0 rgba(0, 0, 0, 0.7)`\n].join(', ')\n\nconst subIconStyle = computed(() => ({\n  fontSize: `${subIconScale}em`,\n  textShadow,\n  ...(offsetX !== 0 && {\n    [positionX === 'left' ? 'left' : 'right']: `${offsetX}px`\n  }),\n  ...(offsetY !== 0 && {\n    [positionY === 'top' ? 'top' : 'bottom']: `${offsetY}px`\n  })\n}))\n</script>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { toValue } from 'vue'\n\nimport OverlayIcon from '@/components/common/OverlayIcon.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\n\nimport type { MenuItem } from './types'\n\nconst { hasSubmenu, item } = defineProps<{\n  hasSubmenu: boolean\n  item: MenuItem\n}>()\n</script>\n\n<template>\n  <OverlayIcon v-if=\"item.overlayIcon\" v-bind=\"item.overlayIcon\" />\n  <i v-else-if=\"item.icon\" :class=\"cn(item.icon, 'size-4 shrink-0')\" />\n  <span class=\"min-w-0 flex-1\">\n    <span class=\"block truncate\">{{ toValue(item.label) }}</span>\n    <span\n      v-if=\"item.description\"\n      class=\"block max-w-64 text-xs whitespace-normal text-muted-foreground\"\n      >{{ toValue(item.description) }}</span\n    >\n  </span>\n  <i\n    v-if=\"item.trailingIcon\"\n    :class=\"cn(item.trailingIcon, 'ml-auto size-4')\"\n  />\n  <span\n    v-if=\"item.badge\"\n    class=\"ml-3 flex items-center gap-1 rounded-full bg-(--primary-background) px-1.5 py-0.5 text-2xs text-base-foreground uppercase\"\n  >\n    {{ item.badge }}\n  </span>\n  <i\n    v-if=\"hasSubmenu\"\n    data-testid=\"menu-item-submenu-indicator\"\n    class=\"ml-auto icon-[lucide--chevron-right] size-4\"\n  />\n  <Switch\n    v-else-if=\"item.presentation === 'switch'\"\n    :model-value=\"toValue(item.checked)\"\n    class=\"pointer-events-none ml-4\"\n    aria-hidden=\"true\"\n    readonly\n    tabindex=\"-1\"\n  />\n  <i\n    v-else-if=\"item.checked !== undefined\"\n    data-testid=\"menu-item-indicator\"\n    :class=\"\n      cn(\n        'ml-auto icon-[lucide--check] size-4',\n        !toValue(item.checked) && 'invisible'\n      )\n    \"\n  />\n  <span\n    v-if=\"item.new && !toValue(item.checked) && !hasSubmenu\"\n    class=\"shrink-0 rounded-full bg-primary-background px-1 text-2xs leading-none font-bold\"\n  >\n    {{ $t('contextMenu.new') }}\n  </span>\n  <span\n    v-if=\"!hasSubmenu && toValue(item.shortcut)\"\n    class=\"ml-auto rounded-sm border border-border-default bg-secondary-background p-1 text-xs text-nowrap text-muted\"\n  >\n    {{ toValue(item.shortcut) }}\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { toValue } from 'vue'\n\nimport OverlayIcon from '@/components/common/OverlayIcon.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\n\nimport type { MenuItem } from './types'\n\nconst { hasSubmenu, item } = defineProps<{\n  hasSubmenu: boolean\n  item: MenuItem\n}>()\n</script>\n\n<template>\n  <OverlayIcon v-if=\"item.overlayIcon\" v-bind=\"item.overlayIcon\" />\n  <i v-else-if=\"item.icon\" :class=\"cn(item.icon, 'size-4 shrink-0')\" />\n  <span class=\"min-w-0 flex-1\">\n    <span class=\"block truncate\">{{ toValue(item.label) }}</span>\n    <span\n      v-if=\"item.description\"\n      class=\"block max-w-64 text-xs whitespace-normal text-muted-foreground\"\n      >{{ toValue(item.description) }}</span\n    >\n  </span>\n  <i\n    v-if=\"item.trailingIcon\"\n    :class=\"cn(item.trailingIcon, 'ml-auto size-4')\"\n  />\n  <span\n    v-if=\"item.badge\"\n    class=\"ml-3 flex items-center gap-1 rounded-full bg-(--primary-background) px-1.5 py-0.5 text-2xs text-base-foreground uppercase\"\n  >\n    {{ item.badge }}\n  </span>\n  <i\n    v-if=\"hasSubmenu\"\n    data-testid=\"menu-item-submenu-indicator\"\n    class=\"ml-auto icon-[lucide--chevron-right] size-4\"\n  />\n  <Switch\n    v-else-if=\"item.presentation === 'switch'\"\n    :model-value=\"toValue(item.checked)\"\n    class=\"pointer-events-none ml-4\"\n    aria-hidden=\"true\"\n    readonly\n    tabindex=\"-1\"\n  />\n  <i\n    v-else-if=\"item.checked !== undefined\"\n    data-testid=\"menu-item-indicator\"\n    :class=\"\n      cn(\n        'ml-auto icon-[lucide--check] size-4',\n        !toValue(item.checked) && 'invisible'\n      )\n    \"\n  />\n  <span\n    v-if=\"item.new && !toValue(item.checked) && !hasSubmenu\"\n    class=\"shrink-0 rounded-full bg-primary-background px-1 text-2xs leading-none font-bold\"\n  >\n    {{ $t('contextMenu.new') }}\n  </span>\n  <span\n    v-if=\"!hasSubmenu && toValue(item.shortcut)\"\n    class=\"ml-auto rounded-sm border border-border-default bg-secondary-background p-1 text-xs text-nowrap text-muted\"\n  >\n    {{ toValue(item.shortcut) }}\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport type { DropdownMenuSeparatorProps } from 'reka-ui'\nimport { DropdownMenuSeparator, useForwardProps } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className, ...restProps } = defineProps<\n  DropdownMenuSeparatorProps & { class?: HTMLAttributes['class'] }\n>()\nconst forwarded = useForwardProps(restProps)\n</script>\n\n<template>\n  <DropdownMenuSeparator\n    v-bind=\"forwarded\"\n    :class=\"cn('my-1 h-px bg-border-subtle', className)\"\n  />\n</template>\n","<script setup lang=\"ts\">\nimport type { DropdownMenuSeparatorProps } from 'reka-ui'\nimport { DropdownMenuSeparator, useForwardProps } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className, ...restProps } = defineProps<\n  DropdownMenuSeparatorProps & { class?: HTMLAttributes['class'] }\n>()\nconst forwarded = useForwardProps(restProps)\n</script>\n\n<template>\n  <DropdownMenuSeparator\n    v-bind=\"forwarded\"\n    :class=\"cn('my-1 h-px bg-border-subtle', className)\"\n  />\n</template>\n","<script setup lang=\"ts\">\nimport type {\n  DropdownMenuRadioItemEmits,\n  DropdownMenuRadioItemProps\n} from 'reka-ui'\nimport { DropdownMenuRadioItem, useForwardPropsEmits } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { menuItemClass } fr